test('addLine and removeLine work together', () => {
  let invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(invoice.ok, true);

  const added = addLine(invoice.value, { sku: 'LOGO-PACK', qty: 1 });
  assert.equal(added.ok, true);
  assert.equal(added.value.lines.length, 2);

  const removed = removeLine(added.value, 'LOGO-PACK');
