test('issueInvoice assigns a number and changes status to issued', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoice.ok, true);
  const r = issueInvoice(invoice.value, []);
  assert.equal(r.ok, true);
  assert.equal(r.value.number, 'INV-2026-0001');
  assert.equal(r.value.status, 'issued');
  assert.equal(r.value.customerId, 'C-001');
});

test('issueInvoice uses the next available number', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(invoice.ok, true);
  const existing = ['INV-2026-0001', 'INV-2026-0002'];
  const r = issueInvoice(invoice.value, existing);
  assert.equal(r.ok, true);
  assert.equal(r.value.number, 'INV-2026-0003');
});

test('issueInvoice handles multiple years correctly', () => {
  const invoice2026 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(invoice2026.ok, true);
  const invoice2027 = createInvoice({
    customerId: 'C-001',
    issueDate: '2027-01-15',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });
  assert.equal(invoice2027.ok, true);

  const existing = ['INV-2026-0010', 'INV-2026-0015'];
  const r2026 = issueInvoice(invoice2026.value, existing);
  const r2027 = issueInvoice(invoice2027.value, existing);

  assert.equal(r2026.value.number, 'INV-2026-0016');
  assert.equal(r2027.value.number, 'INV-2027-0001');
});

